hooks.command:
python3 -c "
import sys, json, os
try:
    data = json.load(sys.stdin)
except Exception:
    sys.exit(0)
file_path = data.get('file_path', '')
if not file_path or not os.path.exists('docs/oracle/index.yaml'):
    sys.exit(0)
try:
    import yaml
except ImportError:
    sys.exit(0)
with open('docs/oracle/index.yaml') as f:
    idx = yaml.safe_load(f)
import fnmatch
matches = []
for entry in idx.get('entries', []):
    for pat in entry.get('paths', []):
        if fnmatch.fnmatch(file_path, pat) or fnmatch.fnmatch(os.path.basename(file_path), pat):
            matches.append(entry)
            break
if not matches:
    sys.exit(0)
print('[Oracle] Ancient wisdom speaks of this artifact:')
for entry in matches:
    print(f\"  * {entry.get('summary', entry['file'])}\")
    doc = f\"docs/oracle/{entry['file']}\"
    if os.path.exists(doc):
        print()
        print(open(doc).read())
"
